using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using HalfAndHalf.Presentation;using NUnit.Framework;using UnityEngine;using Object=UnityEngine.Object;
namespace HalfAndHalf.Tests {
 public sealed class PlaneSortTests {
  const BindingFlags I=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;
  sealed class Fixture:IDisposable {
   internal readonly Mesh Mesh;internal readonly object Prepared;internal readonly Array Points;internal readonly Action Sort;internal readonly FieldInfo Angle,Point,Count;internal readonly object Order;
   internal Fixture(int capacity){Mesh=new Mesh();Mesh.vertices=new[]{Vector3.zero,Vector3.right,Vector3.up};Mesh.normals=new[]{Vector3.forward,Vector3.forward,Vector3.forward};var indices=new int[capacity*3];for(int i=0;i<indices.Length;i++)indices[i]=i%3;Mesh.triangles=indices;var t=typeof(MeshSection).GetNestedType("Prepared",BindingFlags.NonPublic);Prepared=Activator.CreateInstance(t,I,null,new object[]{Mesh},null);Points=(Array)t.GetField("OrderedPlane",I).GetValue(Prepared);Count=t.GetField("PlaneCount",I);Order=t.GetField("Order",I).GetValue(Prepared);var element=Points.GetType().GetElementType();Angle=element.GetField("Angle",I);Point=element.GetField("Point",I);var method=t.GetMethod("SortPlane",I);if(method==null)Object.DestroyImmediate(Mesh);Assert.That(method,Is.Not.Null,"Expose the exact cap sort so per-call allocation can be checked without reflection in the measured loop");Sort=(Action)method.CreateDelegate(typeof(Action),Prepared);}
   internal void Fill(int count,int pattern){Count.SetValue(Prepared,count);var random=new System.Random(347+pattern);float[] special={float.NaN,float.NegativeInfinity,float.PositiveInfinity,0f,BitConverter.Int32BitsToSingle(unchecked((int)0x80000000)),1f,-1f,float.Epsilon,-float.Epsilon};for(int i=0;i<count;i++){object p=Activator.CreateInstance(Points.GetType().GetElementType());Angle.SetValue(p,pattern==0?1f:pattern==1?special[random.Next(special.Length)]:random.Next(-20,21)/10f);Point.SetValue(p,new Vector3(i+1,i%7+.25f,-i-1));Points.SetValue(p,i);}}
   public void Dispose(){if(Mesh!=null)Object.DestroyImmediate(Mesh);}
  }
  [Test] public void WarmCapSortLeavesTheObservedAllocationMarkerUnchanged(){using(var f=new Fixture(64)){f.Fill(64,2);for(int i=0;i<100;i++)f.Sort();using(var recorder=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Memory,"GC.Alloc",1,Unity.Profiling.ProfilerRecorderOptions.StartImmediately|Unity.Profiling.ProfilerRecorderOptions.SumAllSamplesInFrame|Unity.Profiling.ProfilerRecorderOptions.CollectOnlyOnCurrentThread)){long controlStart=recorder.CurrentValue;var control=new byte[4096];GC.KeepAlive(control);long controlValue=recorder.CurrentValue-controlStart;Assert.That(controlValue,Is.GreaterThan(0),"GC.Alloc must observe the positive allocation control; marker values are not byte counts");long quietStart=recorder.CurrentValue;int sum=0;for(int i=0;i<100;i++)sum+=i;long quiet=recorder.CurrentValue-quietStart;Assert.That(quiet,Is.Zero,"No-allocation control must leave the marker unchanged");GC.KeepAlive(sum);long before=recorder.CurrentValue;for(int i=0;i<100;i++)f.Sort();long allocationMarker=recorder.CurrentValue-before;Assert.That(allocationMarker,Is.Zero,"A warm cap sort must avoid the IComparer-to-Comparison delegate allocation");}}}
  [Test] public void TypedSortKeepsLegacyTieAndFloatBoundaryOrderExactly(){using(var f=new Fixture(1024)){var sort=typeof(Array).GetMethods(BindingFlags.Public|BindingFlags.Static).Single(m=>m.Name=="Sort"&&m.IsGenericMethodDefinition&&m.GetGenericArguments().Length==1&&m.GetParameters().Length==4&&m.GetParameters()[1].ParameterType==typeof(int)&&m.GetParameters()[3].ParameterType.IsGenericType&&m.GetParameters()[3].ParameterType.GetGenericTypeDefinition()==typeof(IComparer<>)).MakeGenericMethod(f.Points.GetType().GetElementType());foreach(int count in new[]{0,1,2,3,15,16,17,31,32,33,64,127,128,129,1024})for(int pattern=0;pattern<3;pattern++){f.Fill(count,pattern);var expected=(Array)f.Points.Clone();sort.Invoke(null,new object[]{expected,0,count,f.Order});f.Sort();for(int i=0;i<f.Points.Length;i++){var a=expected.GetValue(i);var b=f.Points.GetValue(i);Assert.That((Vector3)f.Point.GetValue(b),Is.EqualTo((Vector3)f.Point.GetValue(a)),"Point payload/order differs count="+count+" pattern="+pattern+" index="+i);Assert.That(BitConverter.SingleToInt32Bits((float)f.Angle.GetValue(b)),Is.EqualTo(BitConverter.SingleToInt32Bits((float)f.Angle.GetValue(a))));}}}}
  [Test] public void DepthExhaustionKeepsTheInstalledHeapTieOrder(){using(var f=new Fixture(1024)){var t=f.Prepared.GetType();var intro=t.GetMethod("PlaneIntroSort",BindingFlags.Static|BindingFlags.NonPublic);Assert.That(intro,Is.Not.Null,"Depth-zero fallback must preserve the installed heap tie rules");var legacyType=typeof(Array).Assembly.GetType("System.Collections.Generic.ArraySortHelper`1").MakeGenericType(f.Points.GetType().GetElementType());var heap=legacyType.GetMethod("Heapsort",BindingFlags.Static|BindingFlags.NonPublic);Assert.That(heap,Is.Not.Null);var comparison=Delegate.CreateDelegate(typeof(Comparison<>).MakeGenericType(f.Points.GetType().GetElementType()),f.Order,f.Order.GetType().GetMethod("Compare",I));foreach(int count in new[]{17,33,257,1024})foreach(int start in new[]{0,3})for(int pattern=0;pattern<3;pattern++){f.Fill(count+6,pattern);var expected=(Array)f.Points.Clone();heap.Invoke(null,new object[]{expected,start,start+count-1,comparison});intro.Invoke(null,new object[]{f.Points,start,start+count-1,0});for(int i=0;i<f.Points.Length;i++){var a=expected.GetValue(i);var b=f.Points.GetValue(i);Assert.That((Vector3)f.Point.GetValue(b),Is.EqualTo((Vector3)f.Point.GetValue(a)),"Forced heap payload differs");Assert.That(BitConverter.SingleToInt32Bits((float)f.Angle.GetValue(b)),Is.EqualTo(BitConverter.SingleToInt32Bits((float)f.Angle.GetValue(a))));}}}}

  [TestCase(false),TestCase(true)] public void InvalidCountKeepsRangeValidationAndStorageUntouched(bool tooLarge){using(var f=new Fixture(8)){f.Fill(8,2);var before=(Array)f.Points.Clone();f.Count.SetValue(f.Prepared,tooLarge?f.Points.Length+1:-1);var e=Assert.Catch(()=>f.Sort());Assert.That(e.GetType(),Is.EqualTo(tooLarge?typeof(ArgumentException):typeof(ArgumentOutOfRangeException)));for(int i=0;i<f.Points.Length;i++){var a=before.GetValue(i);var b=f.Points.GetValue(i);Assert.That((Vector3)f.Point.GetValue(b),Is.EqualTo((Vector3)f.Point.GetValue(a)));Assert.That(BitConverter.SingleToInt32Bits((float)f.Angle.GetValue(b)),Is.EqualTo(BitConverter.SingleToInt32Bits((float)f.Angle.GetValue(a))));}}}

 }
}
